src/store/modules/user.js:
export default {
  namespaced: true,
  state: () => ({ user: null }),
  getters: {
    isAdmin: (state) => !!(state.user && state.user.admin),
  },
  mutations: {
    SET_USER(state, user) {
      state.user = user;
    },
  },
  actions: {
    async fetchUser({ commit }, id) {
      const res = await fetch('/api/users/' + id);
      commit('SET_USER', await res.json());
    },
  },
};

